write('m03-funnel', 'قیف بازاریابی: AIDA و TOFU / MOFU / BOFU', f'''
<p class="lead">هیچ‌کس با اولین تبلیغ ثبت‌نام نمی‌کند. قیف بازاریابی نشان می‌دهد در هر مرحله چه محتوایی لازم است و کجا مخاطب را از دست می‌دهیم.</p>
{goals(['مدل AIDA را بشناسید.', 'محتوای مناسب TOFU، MOFU و BOFU بسازید.', 'قیف را در SamenCRM اندازه بگیرید.'])}
<h3>AIDA</h3>
{flow([('Attention', 'توجه'), ('Interest', 'علاقه'), ('Desire', 'خواستن'), ('Action', 'اقدام', 'end')])}
<h3>سه طبقه قیف</h3>
<div class="funnel"><div data-v="10000">TOFU – بالای قیف: آگاهی (بازدید، عضویت کانال)</div><div data-v="1500">MOFU – میانه: بررسی (پیام، سرنخ، وبینار)</div><div data-v="250">BOFU – پایین: تصمیم (مشاوره، مدارک، پرداخت)</div><div data-v="70">ثبت‌نام</div></div>
<table><tr><th>طبقه</th><th>هدف</th><th>محتوا</th><th>شاخص</th></tr>
<tr><td>TOFU</td><td>دیده شدن</td><td>ویدیوی کوتاه تجربه دانشجو، «۵ دانشگاه برتر برای پزشکی»</td><td>دسترسی، عضو جدید کانال</td></tr>
<tr><td>MOFU</td><td>جذب سرنخ</td><td>راهنمای PDF هزینه‌ها، وبینار پرسش و پاسخ، ماشین‌حساب هزینه</td><td>تعداد سرنخ، CPL</td></tr>
<tr><td>BOFU</td><td>تبدیل</td><td>مشاوره رایگان، مهلت ثبت‌نام، داستان موفقیت هم‌وطن</td><td>نرخ تبدیل، CAC</td></tr></table>
<div class="tip">در SamenCRM: منبع سرنخ و برچسب کمپین را همیشه پر کنید تا بتوانید از ثبت‌نام به عقب تا محتوای TOFU برسید.</div>
{todo('mfunnel', ['برای هر طبقه سه ایده محتوا بنویسید.', 'یک محتوای MOFU (راهنمای هزینه) آماده کنید و در اسناد بگذارید.', 'قیف ماه گذشته را با اعداد واقعی بکشید.'])}
''')

