write('m07-metrics', 'شاخص‌ها و فرمول‌ها: CPL، CAC، LTV، ROI، ROAS', f'''
<p class="lead">بازاریابی بدون عدد، فقط خرج کردن است. این شاخص‌ها می‌گویند کدام کمپین و کانال پول می‌سازد و کدام پول می‌سوزاند. هر فرمول یک ماشین‌حساب دارد؛ اعداد را عوض کنید و ببینید.</p>
{goals(['هفت شاخص کلیدی را محاسبه و تفسیر کنید.', 'سلامت بازاریابی را با LTV:CAC بسنجید.', 'داده‌های لازم را از SamenCRM دربیاورید.'])}
<h3>۱. هزینه هر سرنخ – CPL</h3>
<div class="formula"><math display="block"><mi>CPL</mi><mo>=</mo><mfrac><mi>هزینه کمپین</mi><mi>تعداد سرنخ</mi></mfrac></math></div>
{calc('cpl')}
<h3>۲. هزینه جذب هر دانشجو – CAC</h3>
<div class="formula"><math display="block"><mi>CAC</mi><mo>=</mo><mfrac><mrow><mi>هزینه بازاریابی</mi><mo>+</mo><mi>هزینه فروش</mi></mrow><mi>دانشجویان جذب‌شده</mi></mfrac></math><p class="fdesc">هزینه فروش شامل حقوق کارشناسان و کمیسیون نمایندگان در همان دوره است.</p></div>
{calc('cac')}
<h3>۳. ارزش طول عمر – LTV</h3>
<div class="formula"><math display="block"><mi>LTV</mi><mo>=</mo><mi>میانگین درآمد هر خرید</mi><mo>×</mo><mi>تعداد خرید</mi><mo>×</mo><mi>حاشیه سود</mi></math><p class="fdesc">یک دانشجو ممکن است چند خدمت بخرد: پذیرش ارشد، ترجمه، ویزای همراه، بعد پذیرش دکتری.</p></div>
{calc('ltv')}
<h3>۴. نسبت LTV به CAC</h3>
<div class="formula"><math display="block"><mfrac><mi>LTV</mi><mi>CAC</mi></mfrac><mo>≥</mo><mn>3</mn></math><p class="fdesc">زیر ۱: هر دانشجو زیان. ۱ تا ۳: سودآور ولی شکننده. ۳ به بالا: سالم؛ می‌توانید با اطمینان بودجه را افزایش دهید.</p></div>
{calc('ltvcac')}
<h3>۵. بازگشت سرمایه – ROI</h3>
<div class="formula"><math display="block"><mi>ROI</mi><mo>=</mo><mfrac><mrow><mi>درآمد</mi><mo>−</mo><mi>هزینه</mi></mrow><mi>هزینه</mi></mfrac><mo>×</mo><mn>100</mn></math></div>
{calc('roi')}
<h3>۶. بازده هزینه تبلیغات – ROAS</h3>
<div class="formula"><math display="block"><mi>ROAS</mi><mo>=</mo><mfrac><mi>درآمد حاصل از تبلیغ</mi><mi>هزینه تبلیغ</mi></mfrac></math></div>
{calc('roas')}
<h3>۷. دوره بازگشت CAC</h3>
<div class="formula"><math display="block"><mi>Payback</mi><mo>=</mo><mfrac><mi>CAC</mi><mi>سود ماهانه هر دانشجو</mi></mfrac></math></div>
{calc('payback')}
<h3>مثال کامل یک کمپین</h3>
<table><tr><th>داده</th><th>مقدار</th></tr><tr><td>هزینه تبلیغ + محتوا</td><td>۴۰ میلیون ریال</td></tr><tr><td>هزینه فروش (سهم حقوق)</td><td>۲۰ میلیون</td></tr><tr><td>سرنخ</td><td>۲۰۰</td></tr><tr><td>ثبت‌نام</td><td>۱۵</td></tr><tr><td>درآمد هر ثبت‌نام</td><td>۴۵ میلیون</td></tr><tr><td>حاشیه سود</td><td>۴۰٪</td></tr></table>
<p>CPL = ۴۰ ÷ ۲۰۰ = ۰٫۲ میلیون. نرخ تبدیل = ۱۵ ÷ ۲۰۰ = ۷٫۵٪. CAC = ۶۰ ÷ ۱۵ = ۴ میلیون. درآمد = ۶۷۵ میلیون؛ سود ناخالص = ۲۷۰ میلیون؛ ROI بر اساس سود = (۲۷۰ − ۶۰) ÷ ۶۰ = ۳۵۰٪.</p>
<div class="warn">ROI را با <b>سود</b> بسنجید نه درآمد، وگرنه کمپین زیان‌ده را سودآور می‌بینید.</div>
{todo('metrics', ['برای کمپین آخر CPL، CAC و ROI را حساب کنید.', 'LTV میانگین را با مدیر مالی تخمین بزنید.', 'نسبت LTV:CAC هر کانال را در یک جدول بنویسید.'])}
''')

write('m08-abtest', 'آزمون A/B و معناداری آماری', f'''
<p class="lead">به‌جای حدس زدن کدام پیام بهتر است، آزمایش کنید: نیمی از مخاطبان پیام A و نیمی پیام B. اما تفاوت کوچک ممکن است شانسی باشد؛ آمار می‌گوید کی می‌توان به نتیجه اعتماد کرد.</p>
{goals(['آزمون A/B درست طراحی کنید.', 'حجم نمونه لازم را حساب کنید.', 'معناداری را با آزمون z بسنجید.'])}
<h3>طراحی</h3>
{flow([('فرضیه', '«نام دانشجو در جمله اول پاسخ را بالا می‌برد»'), ('یک متغیر', 'فقط یک تفاوت'), ('تقسیم تصادفی', 'دو فهرست هم‌اندازه'), ('حجم نمونه', 'قبل از شروع'), ('اجرا هم‌زمان', 'همان روز و ساعت'), ('تحلیل', 'z و p', 'end')])}
<p>در SamenCRM: فهرست هدف را بر اساس رقم آخر شماره پرونده (زوج/فرد) به دو برچسب <code>آزمون: A</code> و <code>آزمون: B</code> تقسیم کنید و دو ارسال هم‌زمان بزنید.</p>
<h3>حجم نمونه لازم</h3>
<div class="formula"><math display="block"><mi>n</mi><mo>=</mo><mfrac><msup><mrow><mo>(</mo><msub><mi>z</mi><mrow><mn>1</mn><mo>−</mo><mi>α</mi><mo>/</mo><mn>2</mn></mrow></msub><msqrt><mrow><mn>2</mn><mover><mi>p</mi><mo>‾</mo></mover><mo>(</mo><mn>1</mn><mo>−</mo><mover><mi>p</mi><mo>‾</mo></mover><mo>)</mo></mrow></msqrt><mo>+</mo><msub><mi>z</mi><mrow><mn>1</mn><mo>−</mo><mi>β</mi></mrow></msub><msqrt><mrow><msub><mi>p</mi><mn>1</mn></msub><mo>(</mo><mn>1</mn><mo>−</mo><msub><mi>p</mi><mn>1</mn></msub><mo>)</mo><mo>+</mo><msub><mi>p</mi><mn>2</mn></msub><mo>(</mo><mn>1</mn><mo>−</mo><msub><mi>p</mi><mn>2</mn></msub><mo>)</mo></mrow></msqrt><mo>)</mo></mrow><mn>2</mn></msup><msup><mrow><mo>(</mo><msub><mi>p</mi><mn>2</mn></msub><mo>−</mo><msub><mi>p</mi><mn>1</mn></msub><mo>)</mo></mrow><mn>2</mn></msup></mfrac></math><p class="fdesc">با اطمینان ۹۵٪ (z=۱٫۹۶) و توان ۸۰٪ (z=۰٫۸۴). هر چه تفاوت مورد انتظار کوچک‌تر باشد، نمونه بزرگ‌تری لازم است.</p></div>
{calc('sample')}
<h3>آزمون z برای دو نسبت</h3>
<div class="formula"><math display="block"><mi>z</mi><mo>=</mo><mfrac><mrow><msub><mover><mi>p</mi><mo>^</mo></mover><mi>B</mi></msub><mo>−</mo><msub><mover><mi>p</mi><mo>^</mo></mover><mi>A</mi></msub></mrow><msqrt><mrow><mover><mi>p</mi><mo>^</mo></mover><mo>(</mo><mn>1</mn><mo>−</mo><mover><mi>p</mi><mo>^</mo></mover><mo>)</mo><mo>(</mo><mfrac><mn>1</mn><msub><mi>n</mi><mi>A</mi></msub></mfrac><mo>+</mo><mfrac><mn>1</mn><msub><mi>n</mi><mi>B</mi></msub></mfrac><mo>)</mo></mrow></msqrt></mfrac></math><p class="fdesc">p̂ نسبت ترکیبی هر دو گروه است. اگر |z| بزرگ‌تر از ۱٫۹۶ (یعنی p کمتر از ۰٫۰۵) باشد، تفاوت با اطمینان ۹۵٪ معنادار است.</p></div>
{calc('abtest')}
<div class="example">A: ۴۸ پاسخ از ۱۰۰۰ (۴٫۸٪)، B: ۷۰ از ۱۰۰۰ (۷٪). z ≈ ۲٫۰۸ و p ≈ ۰٫۰۴ ⇒ B واقعاً بهتر است. اگر B فقط ۵۵ پاسخ داشت، z ≈ ۰٫۷۱ و تفاوت شانسی بود.</div>
<div class="warn">آزمون را وسط راه با دیدن نتیجه زودهنگام متوقف نکنید (Peeking)؛ احتمال نتیجه غلط بالا می‌رود. حجم نمونه را از قبل تعیین کنید.</div>
{todo('ab', ['یک فرضیه برای پیام کمپین بعدی بنویسید.', 'حجم نمونه را با ماشین‌حساب حساب کنید.', 'دو برچسب آزمون بسازید و ارسال هم‌زمان کنید.', 'پس از ۴۸ ساعت معناداری را بسنجید و نتیجه را ثبت کنید.'])}
''')

write('m09-cohort', 'تحلیل کوهورت، نگهداشت و ریزش', f'''
<p class="lead">کوهورت یعنی گروهی که در یک بازه مشترک وارد شده‌اند (مثلاً سرنخ‌های مهر). دنبال کردن هر کوهورت نشان می‌دهد سرعت تبدیل و ماندگاری چطور تغییر می‌کند؛ چیزی که میانگین کلی پنهان می‌کند.</p>
{goals(['جدول کوهورت تبدیل بسازید.', 'نرخ نگهداشت و ریزش را محاسبه کنید.', 'از نتیجه برای بهبود پیگیری استفاده کنید.'])}
<h3>جدول کوهورت تبدیل (نمونه)</h3>
<table><tr><th>کوهورت سرنخ</th><th>تعداد</th><th>ثبت‌نام تا ماه ۰</th><th>ماه ۱</th><th>ماه ۲</th><th>ماه ۳</th></tr>
<tr><td>مرداد</td><td>300</td><td>3٪</td><td>7٪</td><td>9٪</td><td>10٪</td></tr>
<tr><td>شهریور</td><td>420</td><td>4٪</td><td>9٪</td><td>12٪</td><td>–</td></tr>
<tr><td>مهر</td><td>510</td><td>6٪</td><td>11٪</td><td>–</td><td>–</td></tr></table>
<p>تفسیر: از شهریور که برنامه پیگیری ۱۴ روزه اجرا شد، هر کوهورت سریع‌تر و بیشتر تبدیل شده است. میانگین کلی این را نشان نمی‌داد.</p>
<h3>نگهداشت و ریزش</h3>
<div class="formula"><math display="block"><mi>Retention</mi><mo>=</mo><mfrac><mrow><msub><mi>C</mi><mi>E</mi></msub><mo>−</mo><msub><mi>C</mi><mi>N</mi></msub></mrow><msub><mi>C</mi><mi>S</mi></msub></mfrac><mo>,</mo><mspace width="1em"/><mi>Churn</mi><mo>=</mo><mn>1</mn><mo>−</mo><mi>Retention</mi></math><p class="fdesc">C<sub>S</sub>: دانشجویان فعال ابتدای دوره، C<sub>E</sub>: پایان دوره، C<sub>N</sub>: جدیدهای همان دوره. برای خدمات پس از پذیرش (ترم‌های بعد، تمدید اقامت، دکتری) مهم است.</p></div>
{calc('retention')}
<h3>ساخت در SamenCRM</h3>
<ol><li>گزارش مخاطبین با ستون «زمان ایجاد» (ماه) و «وضعیت پذیرش».</li><li>گروه‌بندی بر اساس ماه ایجاد؛ شمارش پذیرش قطعی.</li><li>خروجی اکسل و ساخت جدول درصدها.</li></ol>
{todo('cohort', ['جدول کوهورت سه ماه اخیر را بسازید.', 'بهترین و بدترین کوهورت را مقایسه کنید: چه چیزی فرق داشت؟', 'نرخ نگهداشت دانشجویان ترم گذشته را حساب کنید.'])}
''')

write('m10-attribution', 'انتساب، تخصیص بودجه و پیش‌بینی', f'''
<p class="lead">دانشجو ممکن است اول ویدیوی اینستاگرام ببیند، بعد عضو کانال تلگرام شود و آخر از نماینده ثبت‌نام کند. اعتبار ثبت‌نام مال کیست؟ انتساب به این سؤال پاسخ می‌دهد و تخصیص بودجه را منطقی می‌کند.</p>
{goals(['مدل‌های انتساب را بشناسید.', 'بودجه را بر اساس بازده حاشیه‌ای تقسیم کنید.', 'پیش‌بینی ساده سرنخ و ثبت‌نام بسازید.'])}
<table><tr><th>مدل</th><th>اعتبار به</th><th>مزیت</th><th>عیب</th></tr>
<tr><td>آخرین تماس</td><td>آخرین کانال</td><td>ساده؛ همان «منبع سرنخ»</td><td>کانال‌های آگاهی را دست‌کم می‌گیرد</td></tr>
<tr><td>اولین تماس</td><td>اولین کانال</td><td>ارزش آگاهی را نشان می‌دهد</td><td>بستن را نادیده می‌گیرد</td></tr>
<tr><td>خطی</td><td>همه به‌طور مساوی</td><td>منصفانه</td><td>تفاوت اهمیت را نمی‌بیند</td></tr>
<tr><td>U شکل</td><td>۴۰٪ اول، ۴۰٪ آخر، ۲۰٪ میانه</td><td>تعادل آگاهی و تبدیل</td><td>نیاز به ثبت همه تماس‌ها</td></tr></table>
<div class="tip">برای اجرای انتساب چندکاناله، علاوه بر «منبع سرنخ» (اولین تماس) برچسب‌های <code>کمپین: …</code> را برای هر تعامل اضافه کنید.</div>
<h3>تخصیص بودجه</h3>
<p>بودجه را آن‌جا ببرید که <b>یک ریال بیشتر</b>، بیشترین ثبت‌نام اضافه را بیاورد (بازده حاشیه‌ای)، نه جایی که میانگین بهتر است. هر کانال اشباع دارد.</p>
<div class="example">تلگرام CAC = ۳ میلیون؛ نماینده CAC = ۵ میلیون. ولی تلگرام به اشباع رسیده و ۱۰ میلیون اضافه فقط ۱ ثبت‌نام می‌آورد (CAC حاشیه‌ای ۱۰ م)، در حالی که نماینده جدید با ۱۰ میلیون ۲ ثبت‌نام می‌آورد (۵ م). پول بعدی به نماینده می‌رود.</div>
<h3>پیش‌بینی ساده</h3>
<div class="formula"><math display="block"><mi>ثبت‌نام پیش‌بینی</mi><mo>=</mo><mfrac><mi>بودجه</mi><mi>CPL</mi></mfrac><mo>×</mo><mi>نرخ تبدیل</mi></math></div>
<div class="example">بودجه ۶۰ م، CPL ۰٫۳ م ⇒ ۲۰۰ سرنخ؛ نرخ تبدیل ۷٪ ⇒ ۱۴ ثبت‌نام. برای هدف ۲۰ ثبت‌نام یا CPL باید به ۰٫۲۱ برسد، یا نرخ تبدیل به ۱۰٪، یا بودجه به ۸۶ م.</div>
{todo('attr', ['برای ۲۰ ثبت‌نام اخیر، همه کانال‌هایی که دانشجو از آن‌ها گذشته را از یادداشت‌ها استخراج کنید.', 'اعتبار را با مدل U شکل تقسیم کنید.', 'برای ماه بعد پیش‌بینی ثبت‌نام بر اساس بودجه بنویسید.'])}
''')

write('m11-plan', 'برنامه بازاریابی سالانه و تقویم محتوا', f'''
<p class="lead">بازاریابی آموزش عالی فصلی است: مهلت‌های ثبت‌نام، شروع ترم‌ها، ماه رمضان و محرم، تعطیلات. برنامه سالانه تضمین می‌کند کمپین‌ها به‌موقع آماده شوند.</p>
{goals(['تقویم سالانه کمپین‌ها را بچینید.', 'تقویم محتوای ماهانه بسازید.', 'جلسه بازبینی ماهانه را اجرا کنید.'])}
<h3>تقویم نمونه (شمسی)</h3>
<table><tr><th>فصل</th><th>تمرکز</th><th>کمپین‌ها</th></tr>
<tr><td>فروردین–اردیبهشت</td><td>آگاهی و جذب سرنخ برای مهر</td><td>وبینار «تحصیل در ایران»، محتوای تجربه دانشجویان</td></tr>
<tr><td>خرداد–تیر</td><td>تبدیل؛ مدارک و پذیرش مهر</td><td>کمپین مهلت، پیگیری فشرده، مشاوره رایگان</td></tr>
<tr><td>مرداد–شهریور</td><td>ویزا، ورود، خوش‌آمد</td><td>راهنمای ورود، ارجاع، NPS</td></tr>
<tr><td>مهر–آبان</td><td>جذب برای بهمن</td><td>کمپین ترم بهمن، دکتری</td></tr>
<tr><td>آذر–دی</td><td>تبدیل بهمن</td><td>مهلت‌ها، پیگیری</td></tr>
<tr><td>بهمن–اسفند</td><td>خوش‌آمد و برنامه سال بعد</td><td>بازبینی سال، بودجه‌بندی، تبریک نوروز</td></tr></table>
<h3>تقویم محتوای ماهانه</h3>
<table><tr><th>هفته</th><th>TOFU</th><th>MOFU</th><th>BOFU</th></tr>
<tr><td>۱</td><td>ویدیوی تجربه دانشجو</td><td>راهنمای هزینه</td><td>–</td></tr>
<tr><td>۲</td><td>معرفی یک دانشگاه</td><td>وبینار پرسش و پاسخ</td><td>پیام شخصی به داغ‌ها</td></tr>
<tr><td>۳</td><td>نکته زندگی در ایران</td><td>چک‌لیست مدارک</td><td>مهلت ثبت‌نام</td></tr>
<tr><td>۴</td><td>داستان فارغ‌التحصیل</td><td>–</td><td>پیشنهاد ویژه پایان ماه</td></tr></table>
<h3>جلسه بازبینی ماهانه (۴۵ دقیقه)</h3>
{flow([('عددها', 'قیف، CPL، CAC، ROI'), ('بهترین و بدترین', 'کمپین و کانال'), ('آزمون‌ها', 'نتایج A/B'), ('اعتراض‌ها', 'برچسب‌های اعتراض'), ('تصمیم‌ها', 'بودجه و محتوای ماه بعد', 'end')])}
{todo('plan', ['تقویم سالانه را با مهلت‌های واقعی دانشگاه‌ها کامل کنید.', 'تقویم محتوای ماه بعد را بنویسید.', 'رویداد تکراری «بازبینی بازاریابی» را در تقویم SamenCRM برای اولین شنبه هر ماه بسازید.', 'یک داشبورد «بازاریابی» با گزارش‌های منبع، کمپین و قیف بسازید.'])}
''')
